void Add(int a, int b) // a, b are parameters
{
    Console.WriteLine(a + b);
}

Add(3, 4); // 3, 4 are arguments

int Square(int x)
{
    return x * x;
}

int result = Square(5); // 25

void SetProfile(string name, int age)
{
    Console.WriteLine(name + " - " + age);
}

SetProfile(age: 25, name: "Bob");
SetProfile("Alice", 30);

void Log(string message, bool showTime = true)
{
    if (showTime)
        Console.WriteLine(DateTime.Now + " " + message);
    else
        Console.WriteLine(message);
}

Log("Hello");
Log("Hi", false);

void Sum(int a, int b, int c)
{
    Console.WriteLine(a + b + c);
}

Sum(1, 2, 3); // 6
Sum(10, 20, 30); // 60

void PrintNames(string[] names)
{
    foreach (string name in names)
    {
        Console.WriteLine(name);
    }
}

PrintNames(new string[] {"A", "B"});

void CreateUser(string name, int age = 18, string city = "Unknown")
{
    Console.WriteLine(name + " " + age + " " + city);
}

CreateUser("Alice");
CreateUser("Bob", 25);
CreateUser("Charlie", 30, "NYC");

// Clear and readable
SendEmail(to: "alice@example.com", subject: "Hello", body: "Hi there");

// Order does not matter with named args
SendEmail(body: "Hi there", to: "alice@example.com", subject: "Hello");

